/**
* R2M18_FirstMaskedErrorWarningCtrlBits_t
* RegisterName: FIRST_MASKED_ERROR_WARNING_CTRL
* The register controls the counters and masked_status related to first error and first warning
* Address: 0x270
* ResetValue: 0x00000033
* Read/Write: RW
* FuSa: No
*/
typedef struct  {
	/**
	* BitsName: Reserved_0
	* Description: not used
	*/
	uint32_t Reserved0 : 19;        /*## attribute Reserved0 */
	/**
	* BitsName: first_masked_warning_clr
	* Description: MCU bit to clear the masked status reg in FIRST_MASKED_ERROR_STATUS and FIRST_MASKED_WARNING_STATUS
	*
	*
	* 0 : No action
	* 1 : Reset the masked status reg and counters
	* Read/Write: W
	* Bits: [12]
	* ResetValue: 0b0
	* Source: Reset
	* FuSa: N
	*/
	uint32_t FirstMaskedWarningClr : 1;        /*## attribute FirstMaskedWarningClr */
	/**
	* BitsName: Reserved_1
	* Description: not used
	*/
	uint32_t Reserved1 : 3;        /*## attribute Reserved1 */
	/**
	* BitsName: first_masked_error_clr
	* Description: MCU bit to reset the counters in FIRST_MASKED_ERROR_INFO_REG and FIRST_MASKED_WARNING_INFO_REG
	*
	* 0 : No action
	* 1 : Reset the masked status reg and counters
	* Read/Write: W
	* Bits: [8]
	* ResetValue: 0b0
	* Source: Reset
	* FuSa: N
	*/
	uint32_t FirstMaskedErrorClr : 1;        /*## attribute FirstMaskedErrorClr */
	/**
	* BitsName: Reserved_2
	* Description: not used
	*/
	uint32_t Reserved2 : 2;        /*## attribute Reserved2 */
	/**
	* BitsName: first_masked_warning_clr_ctrl
	* Description: This controls the reset of the registers used in FIRST_MASKED_ERROR_STATUS and FIRST_MASKED_WARNING_STATUS
	*
	* 2'b00 :  No reset of the reg
	* 2'b01 :  Reg reset based on the chirp sequence start signal (hardware based)
	* 2'b10 :  Reg reset based on error_reset coming from pin or register
	* 2'b11 :  Reg reset based on the MCU write into the same register bit 12
	* Note: For setting 2'b01 chirp number and sequence number will be 0 in case chirp trigger via IO per chirp is selected in the Timing Engine (CHIRP_TRIGGER_MODE_CONTROL.chirp_trigger_mode = 2'b11) as the counter is being cleared every chirp. For correct counting it is recommended to use setting 2'b11 or 2'10 and apply a manual reset before each sequence.
	* Read/Write: RW
	* Bits: [5:4]
	* ResetValue: 0b11
	* Source: Reset
	* FuSa: N
	*/
	uint32_t FirstMaskedWarningClrCtrl : 2;        /*## attribute FirstMaskedWarningClrCtrl */
	/**
	* BitsName: Reserved_3
	* Description: not used
	*/
	uint32_t Reserved3 : 2;        /*## attribute Reserved3 */
	/**
	* BitsName: first_masked_error_clr_ctrl
	* Description: This controls the reset of the chirp and sequence counters used in FIRST_MASKED_ERROR_INFO_REG and FIRST_MASKED_WARNING_INFO_REG
	*
	* 2'b00 :  No reset of the counter
	* 2'b01 :  Chirp and Sequence counters reset based on the chirp sequence start signal (hardware based)
	* 2'b10 :  Chirp and Sequence counters reset based on the error_reset coming from pin or register
	* 2'b11 :  Chirp and Sequence counters reset based on the MCU write into the same register bit 8
	* Read/Write: RW
	* Bits: [1:0]
	* ResetValue: 0b11
	* Source: Reset
	* FuSa: N
	*/
	uint32_t FirstMaskedErrorClrCtrl : 2;        /*## attribute FirstMaskedErrorClrCtrl */
}R2M18_FirstMaskedErrorWarningCtrlBits_t;
